import "./App.css";
import Navbar from "./components/Navbar.tsx";
import { BrowserRouter, Routes, Route, useLocation } from "react-router-dom";
import { useCallback, useEffect, useState } from "react";
import Home from "./Pages/Home.tsx";
import Explore from "./Pages/Explore.tsx";
import MovieDetails from "./Pages/MovieDetails.tsx";
import Toprated from "./Pages/Toprated.jsx";
import Actordetails from "./Pages/Actordetails.tsx";
import LoginPage from "./Pages/LoginPage.tsx";
import ProfilePage from "./Pages/ProfilePage.tsx";
import ActorProfilePage from "./Pages/ActorProfilePage.tsx";
import ConditionalRoute from './components/ConditionalRoute.tsx';
import ProtectedRoute from './components/ProtectedRoute.tsx';
import Tvdetails from './Pages/Tvdetails.tsx'
import FavActors from './Pages/FavActors.tsx'
import Trending from './Pages/Trending.tsx';
import Watchlist from "./Pages/Watchlist.tsx";
import Upcoming from "./Pages/Upcoming.tsx";
import SearchResults from "./Pages/SearchResults.tsx";
import HistoryPage from "./Pages/History.tsx";
import License from "./components/License.tsx";
import CommandMenu from "./components/CommandMenu.tsx";
import DirectorsCut from "./Pages/DirectorsCut.tsx";

const AppRoutes = ({ isCmdMenuOpen, setIsCmdMenuOpen, isDark, toggleDark }) => {
  const location = useLocation();

  return (
    <>
      {location.pathname !== "/login" && <Navbar />}
      <Routes>
        <Route path="/login" element={<LoginPage />} />
        <Route path="/" element={<ConditionalRoute />} />

        <Route element={<ProtectedRoute />}>
          <Route path="/home" element={<Home />} />
          <Route path="/profile" element={<ProfilePage />} />
          <Route path="/actors" element={<ActorProfilePage />} />
          <Route path="/explore" element={<Explore />} />
          <Route path="/movie/:id" element={<MovieDetails />} />
          <Route path="/actor/:id" element={<Actordetails />} />
          <Route path="tv/:id" element={<Tvdetails />} />
          <Route path="/top-rated" element={<Toprated />} />
          <Route path="/fav-actors" element={<FavActors />} />
          <Route path="/trending" element={<Trending />} />
          <Route path="/watchlist" element={<Watchlist />} />
          <Route path="/upcoming" element={<Upcoming />} />
          <Route path="/search" element={<SearchResults />} />
          <Route path="/history" element={<HistoryPage />} />
          <Route path="/directors-cut" element={<DirectorsCut />} />
        </Route>
      </Routes>
    </>
  );
};


function App() {
  const [isCmdMenuOpen, setIsCmdMenuOpen] = useState(false);
  const [isDark, setIsDark] = useState(true);

  // Theme is handled via a dataset attribute so Tailwind's `dark:` classes can be used if needed.
  useEffect(() => {
    const root = document.documentElement;
    root.dataset.theme = isDark ? 'dark' : 'light';
    // Optional: also set the Tailwind `dark` class for any `dark:*` usage.
    root.classList.toggle('dark', isDark);
  }, [isDark]);

  const toggleDark = useCallback(() => {
    setIsDark((v) => !v);
  }, []);

  useEffect(() => {
    const onKeyDown = (e) => {
      const isMac = navigator.platform.toLowerCase().includes('mac');
      const mod = isMac ? e.metaKey : e.ctrlKey;
      const key = e.key?.toLowerCase();

      if (mod && key === 'k') {
        e.preventDefault();
        setIsCmdMenuOpen(true);
      }

      if (e.key === 'Escape') {
        setIsCmdMenuOpen(false);
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, []);

  return (
    <BrowserRouter>
      <div className="min-h-screen bg-black text-white relative">
        <AppRoutes
          isCmdMenuOpen={isCmdMenuOpen}
          setIsCmdMenuOpen={setIsCmdMenuOpen}
          isDark={isDark}
          toggleDark={toggleDark}
        />
        <CommandMenu
          isOpen={isCmdMenuOpen}
          onClose={() => setIsCmdMenuOpen(false)}
        />
        <License />
      </div>
    </BrowserRouter>
  );
}

export default App;